{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C43"],
      "claim": "Perindoprilat oral bioavailability in young healthy subjects was 19±7%, below the 20% threshold; the 30% value in cirrhotic patients is less transferable."
    },
    {
      "card_ids": ["C33"],
      "claim": "Oxybutynin absolute oral bioavailability was 6.2±1.2% in healthy volunteers, well below 20%."
    },
    {
      "card_ids": ["C49"],
      "claim": "Ipratropium bromide absolute oral bioavailability was 3.3% (range 0.9–6.1%) in healthy volunteers, below 20%; a single 30-mg estimate of 32% is an outlier."
    }
  ],
  "confidence": "high",
  "contradictory_card_ids": ["C45", "C40"],
  "decision_summary": "Across the transferred evidence, ordinary-condition absolute oral bioavailability values are consistently below 20%; high values come from altered conditions or isolated doses, so low is predicted.",
  "evidence_gaps": [
    "C12 under molecule 7 refers to drospirenone, a different compound, and was discounted as a provenance conflict.",
    "High values from cirrhotic patients (C45), CsA co-administration (C36/C22), and a single 30-mg ipratropium dose (C40) are less transferable to ordinary conditions."
  ],
  "new_evidence_assessment": [],
  "prediction_basis_card_ids": ["C43", "C33", "C49"],
  "revision_action": "initial",
  "supportive_card_ids": ["C43", "C33", "C49"]
}

